// Flag data: countries, then territories, regions and organisations.
// ---------- DATA ----------
// Each: [code, name, region, capital, meaning]
const EU="Europe",AS="Asia",AF="Africa",AM="Americas",OC="Oceania";
const RAW=[
["al","Albania",EU,"Tirana","A two-headed black eagle on red. The eagle was the emblem of Skanderbeg, the 15th-century hero who held off the Ottomans, and Albanians' own name for their country, Shqipëri, is often glossed as 'land of eagles'."],
["ad","Andorra",EU,"Andorra la Vella","Blue, yellow and red vertical stripes with the coat of arms. Blue and red are shared with France, yellow and red with Catalonia; the arms recall the Bishop of Urgell and the Count of Foix, the origins of Andorra's two co-princes. Without the arms it would match Romania and Chad."],
["at","Austria",EU,"Vienna","Red, white, red. Legend says Duke Leopold V's white tunic was soaked in blood after a battle in 1191 except for the strip under his belt. One of the oldest flag designs still in use."],
["by","Belarus",EU,"Minsk","Red over green with a red-on-white woven pattern at the hoist, a traditional ornament of the kind used on the rushnyk (ritual towel). There is no official meaning, but red is said to stand for freedom and the sacrifices of past generations, green for life."],
["be","Belgium",EU,"Brussels","Black, yellow, red in vertical stripes, from the arms of the Duchy of Brabant: a gold lion with red claws and tongue on black. The vertical layout copies France; Germany uses similar colours horizontally."],
["ba","Bosnia and Herzegovina",EU,"Sarajevo","A yellow triangle on blue with a diagonal row of white stars. The three points stand for the three main peoples (Bosniaks, Croats, Serbs) and echo the country's shape; the blue and stars nod to the EU flag. Designed in 1998 to favour no group."],
["bg","Bulgaria",EU,"Sofia","White for peace, green for farmland, red for courage. It is the Russian white-blue-red with blue swapped for green."],
["hr","Croatia",EU,"Zagreb","Red, white, blue with the red-and-white checkerboard shield (šahovnica), topped by a crown of five small historical crests. The checkerboard is the giveaway among pan-Slavic tricolours."],
["cy","Cyprus",EU,"Nicosia","A copper-orange silhouette of the island (copper may have given Cyprus its name) over two olive branches for peace between Greek and Turkish Cypriots. The white field deliberately avoids both Greek blue and Turkish red."],
["cz","Czechia",EU,"Prague","White and red are Bohemia's colours; the blue triangle at the hoist was added in 1920 so the flag would no longer be identical to Poland's."],
["dk","Denmark",EU,"Copenhagen","The Dannebrog: a white Nordic cross on red. Legend says it fell from the sky during a battle in Estonia in 1219. Often called the oldest continuously used national flag, and the model for every other Nordic cross."],
["ee","Estonia",EU,"Tallinn","Blue for the sky, black for attachment to the soil of the homeland, white for purity, hard work and commitment, in the popular reading from the poet Martin Lipp. Chosen by a student society in 1881."],
["fi","Finland",EU,"Helsinki","A blue Nordic cross on white: the country's thousands of lakes and its winter snow."],
["fr","France",EU,"Paris","The tricolour of the Revolution. White was the colour of the monarchy; blue and red were the colours of Paris. It inspired dozens of other vertical tricolours."],
["de","Germany",EU,"Berlin","Black, red and gold come from the uniforms of the Lützow Free Corps in the Napoleonic wars (black coats, red facings, gold buttons), taken up by the liberal revolution of 1848."],
["gr","Greece",EU,"Athens","Nine blue-and-white stripes, often said to count the syllables of 'Eleftheria i Thanatos' (Freedom or Death). The cross in the canton stands for Christianity."],
["hu","Hungary",EU,"Budapest","Red for strength, white for faithfulness, green for hope, the colours of the medieval Hungarian arms. Note the order: Bulgaria is white on top, Iran has green on top."],
["is","Iceland",EU,"Reykjavík","A red cross edged in white on blue: fire (volcanoes), ice (glaciers) and the sea. It is Norway's colours inverted: Norway is red with a blue cross."],
["ie","Ireland",EU,"Dublin","Green for the Gaelic and Catholic tradition, orange for the Protestant followers of William of Orange, and white for peace between them. Côte d'Ivoire uses the same colours reversed, with orange at the hoist and shorter proportions."],
["it","Italy",EU,"Rome","Green, white, red, modelled on the French tricolour; the colours were already used by the Milanese civic guard and on patriots' cockades in 1796. Mexico uses the same stripes with an eagle at centre."],
["xk","Kosovo",EU,"Pristina","A gold map of the country under six white stars for its six main communities, on blue. Adopted at independence in 2008; Cyprus is the only other flag that uses a map."],
["lv","Latvia",EU,"Riga","Deep carmine with a white stripe. Legend tells of a wounded leader wrapped in a white sheet that was stained red on both sides. The design is recorded in a 13th-century chronicle."],
["li","Liechtenstein",EU,"Vaduz","Blue over red with a gold crown. The crown was added in 1937 after the team arrived at the 1936 Berlin Olympics and discovered Haiti's flag was identical."],
["lt","Lithuania",EU,"Vilnius","Yellow for the sun and prosperity, green for forests and hope, red for the blood shed for the homeland."],
["lu","Luxembourg",EU,"Luxembourg","Red, white and a light, bright blue, from the Grand Duke's arms (a red lion on white-and-blue stripes). The lighter blue is the clue that separates it from the Netherlands."],
["mt","Malta",EU,"Valletta","White and red, traditionally said to come from the colours of Count Roger of Sicily in 1091, though historians now treat that story as a myth. The George Cross in the corner was awarded to the whole island in 1942 for its bravery during the Second World War."],
["md","Moldova",EU,"Chișinău","Blue, yellow, red like Romania (shared language and history), with Moldova's arms: an eagle holding a shield with an aurochs head, star, rose and crescent."],
["mc","Monaco",EU,"Monaco","Red over white, the heraldic colours of the Grimaldi family who have ruled since the 13th century. Indonesia's flag is the same except for its proportions."],
["me","Montenegro",EU,"Podgorica","A gold-bordered red field with the double-headed eagle of the Petrović dynasty; the lion on its chest stands for the Church."],
["nl","Netherlands",EU,"Amsterdam","Originally orange, white and blue for William of Orange, but from the mid-1600s red replaced the orange, apparently as the Republic distanced itself from the House of Orange. The oldest tricolour in continuous use, and said to have inspired Russia's."],
["mk","North Macedonia",EU,"Skopje","A gold sun with eight widening rays on red, 'the new sun of liberty' from the national anthem. It replaced the Vergina Sun in 1995 after a dispute with Greece over that ancient symbol."],
["no","Norway",EU,"Oslo","A blue cross outlined in white on red, designed by Fredrik Meltzer in 1821. Red and blue recall the old union partners Denmark and Sweden, while red, white and blue together were also read as the colours of liberty (France, the US), laid on the Nordic cross."],
["pl","Poland",EU,"Warsaw","White over red, from the white eagle on a red shield in Poland's arms. Indonesia and Monaco are the same flag upside down."],
["pt","Portugal",EU,"Lisbon","Green for hope and red for the blood of those who died defending the nation, the colours of the republicans who took power in 1910. The armillary sphere recalls Portugal's seafaring in the Age of Discovery; the shield carries five small shields and seven castles inherited from the medieval kingdom."],
["ro","Romania",EU,"Bucharest","Blue, yellow, red: colours found on the old insignia of both Wallachia and Moldavia, raised together as a tricolour in 1848. Chad's flag is almost identical; officially Chad's blue is indigo and Romania's cobalt."],
["ru","Russia",EU,"Moscow","White, blue, red, adopted by Peter the Great in the 1690s, reportedly after seeing the Dutch flag. These became the pan-Slavic colours used by Slovakia, Slovenia and Serbia."],
["sm","San Marino",EU,"San Marino","White (for peace) over light blue (for liberty), with arms showing three towers on the three peaks of Monte Titano."],
["rs","Serbia",EU,"Belgrade","Pan-Slavic red, blue, white with the arms: a white double-headed eagle and a cross with four firesteels, read as four Cyrillic 'C's for 'Only Unity Saves the Serbs'."],
["sk","Slovakia",EU,"Bratislava","White, blue, red pan-Slavic stripes with a shield: a white double cross on three blue hills for the Tatra, Fatra and Mátra ranges."],
["si","Slovenia",EU,"Ljubljana","White, blue, red with a shield showing Mount Triglav, the highest peak, three gold stars from the Counts of Celje, and wavy lines for the sea and rivers."],
["es","Spain",EU,"Madrid","Red and yellow, the colours of the Crown of Aragon, picked in 1785 because they were easy to spot at sea. The arms combine Castile, León, Aragon, Navarre and Granada between the Pillars of Hercules."],
["se","Sweden",EU,"Stockholm","A yellow Nordic cross on blue, believed to be inspired by the national coat of arms of the 1440s, a blue shield quartered by a gold cross."],
["ch","Switzerland",EU,"Bern","A white cross on red, from the field sign of the Swiss Confederates in the 14th century. One of only two square national flags; the other is Vatican City's."],
["ua","Ukraine",EU,"Kyiv","Popularly read as blue sky over a golden wheat field. Blue and yellow were common on medieval coats of arms in Galicia, such as Lviv's golden lion on blue."],
["gb","United Kingdom",EU,"London","The Union Jack layers three crosses: St George (England, red on white), St Andrew (Scotland, white diagonal on blue) and St Patrick (Ireland, red diagonal)."],
["va","Vatican City",EU,"Vatican City","Yellow and white, the gold and silver of the crossed keys of St Peter, under the papal tiara. Square, like Switzerland's."],

["af","Afghanistan",AS,"Kabul","Black for the past, red for blood shed for independence, green for hope and Islam, with an emblem of a mosque, pulpit and wheat. This is the republic's flag; the Taliban replaced it in 2021 with a white banner bearing the shahada, and this design is still widely used by Afghans abroad."],
["am","Armenia",AS,"Yerevan","Red for the Armenian Highland and the people's struggle for survival and their Christian faith, blue for the will to live under peaceful skies, orange (often called apricot) for creative talent and hard work."],
["az","Azerbaijan",AS,"Baku","Blue for Turkic heritage, red for progress and modernity, green for Islam. The eight-pointed star stands for the eight branches of the Turkic peoples."],
["bh","Bahrain",AS,"Manama","Red with a white band joined by five white points, one for each of the Five Pillars of Islam. Qatar's neighbouring flag is maroon with nine points."],
["bd","Bangladesh",AS,"Dhaka","A red disc, the sun rising over Bengal and the blood of the 1971 war, on green for the lush land. The disc sits slightly toward the hoist so it looks centred when flying. Japan's is red on white; Palau's is yellow on blue."],
["bt","Bhutan",AS,"Thimphu","A white thunder dragon (druk) clutching jewels across a diagonal of yellow (the secular monarchy) and orange (Buddhism). Bhutan calls itself Druk Yul, Land of the Thunder Dragon."],
["bn","Brunei",AS,"Bandar Seri Begawan","Yellow for royalty, crossed by white and black stripes for the sultan's two chief ministers. The red crest holds a crescent reading 'Always in service with God's guidance' and a banner naming 'Brunei, abode of peace'."],
["kh","Cambodia",AS,"Phnom Penh","A white Angkor Wat on a red band between blue bands. One of very few national flags showing a building."],
["cn","China",AS,"Beijing","Red for the revolution. The large star is the Communist Party and the four small stars are the classes of the people united around it."],
["ge","Georgia",AS,"Tbilisi","The 'five-cross flag': a large red St George's cross with four small Bolnisi crosses, a medieval Georgian design revived in 2004."],
["in","India",AS,"New Delhi","Saffron for courage and sacrifice, white for truth and peace, green for faith and chivalry. The blue Ashoka Chakra at centre is a 24-spoke wheel of law. Niger is the look-alike: orange, white, green with a plain orange disc."],
["id","Indonesia",AS,"Jakarta","Red for courage and white for purity, colours used by the 13th-century Majapahit empire. Nearly identical to Monaco's apart from proportions and shade of red; Poland is the reverse."],
["ir","Iran",AS,"Tehran","Green, white, red with a stylised 'Allah' emblem at centre, often seen as a tulip, and 'Allahu Akbar' written 22 times along the stripe edges for 22 Bahman, the date of the 1979 revolution."],
["iq","Iraq",AS,"Baghdad","Arab Liberation red, white, black with 'Allahu Akbar' in green Kufic script across the white band. Egypt and Yemen share the stripes; the script is Iraq's tell."],
["il","Israel",AS,"Jerusalem","The two blue stripes recall the tallit, the Jewish prayer shawl, with the Star of David at centre."],
["jp","Japan",AS,"Tokyo","The Hinomaru, 'circle of the sun': a red disc on white for the land of the rising sun."],
["jo","Jordan",AS,"Amman","The Arab Revolt colours: black (Abbasid), white (Umayyad) and green (Fatimid) caliphates, with a red triangle for the Hashemite dynasty. The seven-pointed star stands for the seven verses of the Quran's opening chapter; Palestine's flag is the same without the star."],
["kz","Kazakhstan",AS,"Astana","Sky blue for the open sky and the Turkic peoples, a 32-rayed gold sun above a soaring steppe eagle, and a traditional ornament running along the hoist."],
["kw","Kuwait",AS,"Kuwait City","Arab Revolt colours with a black trapezoid at the hoist. A poem supplies the meanings: green for the land, white for deeds, red for swords, black for the battlefield."],
["kg","Kyrgyzstan",AS,"Bishkek","A red field with a 40-rayed sun for the 40 tribes united by the hero Manas. Inside the sun is a tunduk, the circular crown of a yurt seen from below."],
["la","Laos",AS,"Vientiane","Red for blood shed in the struggle, blue for the Mekong and prosperity. The white disc is the full moon over the river, and national unity. Thailand has similar red-and-blue bands but no disc."],
["lb","Lebanon",AS,"Beirut","A green cedar of Lebanon, the tree of the Bible and of Lebanese identity, on white for peace between two red bands for sacrifice."],
["my","Malaysia",AS,"Kuala Lumpur","Fourteen stripes and a 14-pointed star for the 13 states plus the federal territories; the crescent is Islam and yellow is the royal colour. The stripes-and-canton layout echoes the US and Liberian flags."],
["mv","Maldives",AS,"Malé","Red for the blood of the nation's heroes framing a green rectangle for peace and prosperity, with a white crescent for Islam."],
["mn","Mongolia",AS,"Ulaanbaatar","The Soyombo symbol in yellow on a red stripe beside blue for the eternal sky. The symbol stacks fire, sun, moon, arrows and a yin-yang, each with its own meaning."],
["mm","Myanmar",AS,"Naypyidaw","Yellow for solidarity, green for peace and greenery, red for courage, with a large white star for purity, honesty, compassion and power. Adopted in 2010; it looks like Lithuania's with a star."],
["np","Nepal",AS,"Kathmandu","The only non-rectangular national flag: two stacked pennants once flown by rival branches of the ruling dynasty. The moon is calm and purity of spirit, the sun is fierce resolve; crimson is bravery and the colour of the rhododendron."],
["kp","North Korea",AS,"Pyongyang","Red for revolution, blue for sovereignty and peace, white for purity; a red star for communism inside a white disc."],
["om","Oman",AS,"Muscat","White for peace, red for battles fought, green for the Jebel Akhdar (Green Mountain). The emblem is a khanjar dagger over two crossed swords."],
["pk","Pakistan",AS,"Islamabad","Green for Islam and the Muslim majority, the white stripe for religious minorities. The crescent is progress and the star is light and knowledge."],
["ps","Palestine",AS,"Ramallah (de facto)","The Arab Revolt flag of 1916: black, white and green stripes with a red triangle. Jordan's is identical but adds a white seven-pointed star in the triangle."],
["ph","Philippines",AS,"Manila","The sun's eight rays are the first eight provinces that rose against Spain; the three stars are Luzon, Visayas and Mindanao. In wartime the flag is flown with the red stripe on top."],
["qa","Qatar",AS,"Doha","Maroon (the natural dye darkened in the sun) with a nine-point serrated white band marking Qatar as the ninth 'reconciled emirate' after its 1916 treaty with Britain. Bahrain's is red with five points."],
["sa","Saudi Arabia",AS,"Riyadh","Green with the shahada, the Islamic declaration of faith, above a sword. It is made identically on both sides so the text reads correctly either way, and it is never flown at half-mast."],
["sg","Singapore",AS,"Singapore","Red for universal brotherhood, white for purity. The crescent is a young nation on the rise and the five stars are democracy, peace, progress, justice and equality. Without the crescent and stars it would be Indonesia's flag."],
["kr","South Korea",AS,"Seoul","The red-and-blue taegeuk (the balance of yin and yang) surrounded by four black trigrams from the I Ching: heaven, earth, water and fire."],
["lk","Sri Lanka",AS,"Sri Jayawardenepura Kotte","A gold lion holding a sword, for the Sinhalese people, on maroon with four bo-tree leaves for Buddhist virtues. The green and orange stripes stand for the Muslim and Tamil minorities."],
["sy","Syria",AS,"Damascus","Green, white, black with three red stars: the flag of Syria's independence in 1946, readopted in 2025 after the fall of the Assad government. The three stars originally stood for the three districts of the 1930s state."],
["tw","Taiwan",AS,"Taipei","'Blue sky, white sun, and a wholly red earth': the white sun with twelve rays (the twelve traditional hours) in a blue canton, from the Republic of China's 1928 flag."],
["tj","Tajikistan",AS,"Dushanbe","Red, white, green (Iran's colours in reverse order), but with a gold crown under seven stars at centre. White stands for cotton, green for the valleys."],
["th","Thailand",AS,"Bangkok","Red for the nation, white for religion, blue for the monarchy. The blue centre band was added in 1917, by one account to match the colours of the WWI Allies. Costa Rica is the same pattern with blue and red swapped."],
["tl","Timor-Leste",AS,"Dili","A black triangle (obscurantism to be overcome) on a yellow one (the country's wealth) on red (the struggle for liberation), with a white star, the light that guides, for peace."],
["tr","Türkiye",AS,"Ankara","A white crescent and star on red, inherited from the Ottoman Empire. Tunisia's flag puts the same crescent and star in a white disc."],
["tm","Turkmenistan",AS,"Ashgabat","Green with a vertical carpet stripe showing five guls, traditional carpet motifs of the five major tribes, plus a crescent and five stars. Often called the most intricate national flag."],
["ae","United Arab Emirates",AS,"Abu Dhabi","Pan-Arab colours with a red vertical band at the hoist, chosen in a 1971 design contest. Green for growth and prosperity, white for peace and purity, black for dignity, red for the people's sacrifices."],
["uz","Uzbekistan",AS,"Tashkent","Blue for sky and water, white for peace, green for nature, with thin red lines for the power of life. A crescent for a new nation and twelve stars for the provinces."],
["vn","Vietnam",AS,"Hanoi","A gold five-pointed star on revolutionary red; the points stand for workers, peasants, soldiers, intellectuals and traders."],
["ye","Yemen",AS,"Sanaa","The plain Arab Liberation tricolour of red, white and black, adopted in 1990 when North and South Yemen united. The only one of the group with no emblem."],

["dz","Algeria",AF,"Algiers","Green for Islam and white for purity, with a red crescent and star: the red carries the meaning of jihad, the struggle, and the star's five points are the five pillars of Islam."],
["ao","Angola",AF,"Luanda","Red for blood shed and black for Africa. The emblem of a half gearwheel, machete and star is often compared to the Soviet hammer and sickle."],
["bj","Benin",AF,"Porto-Novo","Pan-African colours: green for hope, yellow for the nation's wealth, red for the courage of the ancestors."],
["bw","Botswana",AF,"Gaborone","Light blue for water and rain ('pula', which is also the currency and a greeting), with black and white stripes for racial harmony and the zebra."],
["bf","Burkina Faso",AF,"Ouagadougou","Red for the revolution and green for abundance, with a yellow star to guide it. Adopted in 1984 together with the country's new name."],
["bi","Burundi",AF,"Gitega","A white diagonal cross for peace with three red stars for unity, work and progress (and the three peoples: Hutu, Tutsi, Twa). Red for the struggle, green for hope."],
["cm","Cameroon",AF,"Yaoundé","Pan-African vertical tricolour with a gold star of unity. Green for the southern forests, yellow for the northern savanna, red for unity between them."],
["cv","Cabo Verde",AF,"Praia","Blue for the ocean, white and red for peace and effort. The ring of ten stars is the ten main islands."],
["cf","Central African Republic",AF,"Bangui","Pan-African and French colours together, crossed by a red stripe for the blood that binds them, with a yellow star of hope."],
["td","Chad",AF,"N'Djamena","Indigo blue for Lake Chad and the country's Black African heritage, yellow for the sands of the Sahara, red for the blood shed for independence. Nearly identical to Romania's; officially Chad's blue is indigo and Romania's cobalt."],
["km","Comoros",AF,"Moroni","Four stripes and four stars for the four islands, including Mayotte, which Comoros claims from France. The crescent is Islam."],
["cg","Republic of the Congo",AF,"Brazzaville","Pan-African green, yellow and red arranged diagonally. Green for forests and farming, yellow for friendship and nobility; the meaning of red was never officially explained."],
["cd","Democratic Republic of the Congo",AF,"Kinshasa","Sky blue for peace, crossed by a red diagonal (blood of martyrs) edged in yellow (the country's wealth), with a star for the future."],
["ci","Côte d'Ivoire",AF,"Yamoussoukro","Orange for the northern savanna and growth, white for peace, green for the forests and hope. It is Ireland's flag reversed: orange at the hoist."],
["dj","Djibouti",AF,"Djibouti","Blue for the Issa (Somali) people and the sea, green for the Afar people and the earth, white for peace, and a red star for unity."],
["eg","Egypt",AF,"Cairo","Arab Liberation red (blood shed against colonial rule), white (purity of heart), black (darkness overcome), with the gold Eagle of Saladin at centre."],
["gq","Equatorial Guinea",AF,"Malabo","Green, white, red with a blue triangle for the sea. The arms show a silk-cotton tree and six stars for the mainland plus five islands."],
["er","Eritrea",AF,"Asmara","A red triangle (blood of the independence war) between green (agriculture) and blue (the Red Sea), with an olive wreath from the 1952 flag."],
["sz","Eswatini",AF,"Mbabane","A black-and-white Nguni shield of the Emabutfo regiment with two spears and a staff, on a crimson band for past battles between blue bands for peace. The shield's two colours show black and white people living together."],
["et","Ethiopia",AF,"Addis Ababa","Green, yellow, red: the original pan-African colours, copied by many states after Ethiopia kept its independence. The blue disc with a star was added in 1996."],
["ga","Gabon",AF,"Libreville","Green for the forests, yellow for the equator and the sun, blue for the sea."],
["gm","The Gambia",AF,"Banjul","Blue for the River Gambia flowing between red (the sun and savanna) and green (the forests), with white lines for peace."],
["gh","Ghana",AF,"Accra","In 1957 it became the second African flag, after Ethiopia's, to use pan-African red, yellow and green. The black star, taken from Marcus Garvey's Black Star Line flag, stands for the emancipation of Africa."],
["gn","Guinea",AF,"Conakry","Red for sacrifice, yellow for the sun and wealth, green for vegetation, in vertical stripes. Mali's flag is the mirror image."],
["gw","Guinea-Bissau",AF,"Bissau","Pan-African colours with a black star for the people of Africa and the PAIGC's leadership on a red vertical band: a layout borrowed from Ghana and Guinea."],
["ke","Kenya",AF,"Nairobi","Black for the people, red for blood, green for the land, with white lines for peace. The Maasai shield and spears stand for the defence of freedom."],
["ls","Lesotho",AF,"Maseru","A black Basotho hat (mokorotlo) on a white stripe for peace, between blue for rain and green for prosperity."],
["lr","Liberia",AF,"Monrovia","Modelled on the US flag by settlers from America. Eleven stripes for the signers of the 1847 declaration of independence; one star for the first independent republic in Africa."],
["ly","Libya",AF,"Tripoli","Red, black and green with a crescent and star. The black band is the Senussi banner of Cyrenaica. Restored in 2011 after more than three decades of Gaddafi's plain green flag."],
["mg","Madagascar",AF,"Antananarivo","White and red were the royal colours of the Merina kingdom; green stands for hope and the island's greenery."],
["mw","Malawi",AF,"Lilongwe","A red rising sun over black (the African people), red (blood) and green (nature): the dawn of freedom in Africa."],
["ml","Mali",AF,"Bamako","Green, yellow, red vertical pan-African tricolour. Guinea's is the mirror image: red at the hoist."],
["mr","Mauritania",AF,"Nouakchott","Green with a gold crescent and star for Islam. The red bands were added in 2017 for the blood of those who fought French rule."],
["mu","Mauritius",AF,"Port Louis","Four stripes: red for the struggle, blue for the Indian Ocean, yellow for the new light of independence, green for agriculture."],
["ma","Morocco",AF,"Rabat","Red, the colour of the Alaouite dynasty, with a green five-pointed Seal of Solomon for the five pillars of Islam."],
["mz","Mozambique",AF,"Maputo","The only national flag with a modern firearm: an AK-47 crossed with a hoe over an open book, on a star for international solidarity."],
["na","Namibia",AF,"Windhoek","A sun for life and energy over blue (sky and ocean), red (the people) and green (the land)."],
["ne","Niger",AF,"Niamey","No meanings are official, but orange is read as the Sahara, white as the Sahel and green as the fertile south, with an orange disc for the sun. Same colours as India, which has a blue wheel instead."],
["ng","Nigeria",AF,"Abuja","Green for agriculture and the land, white for peace and unity. Chosen in a 1959 competition; the judges removed the red sun from the winning entry."],
["rw","Rwanda",AF,"Kigali","Blue for happiness and peace, yellow for economic development, green for prosperity, with a sun of enlightenment. Adopted in 2001 to drop the colours associated with the 1994 genocide."],
["st","São Tomé and Príncipe",AF,"São Tomé","Pan-African colours with two black stars for the two islands and a red triangle for the independence struggle."],
["sn","Senegal",AF,"Dakar","The same vertical tricolour as Mali, with a green star at centre whose five points recall the human figure on the old Mali Federation flag."],
["sc","Seychelles",AF,"Victoria","Five bands fanning out from the corner for a dynamic young nation: blue (sea and sky), yellow (sun), red (the people), white (justice), green (the land)."],
["sl","Sierra Leone",AF,"Freetown","Green for agriculture and the mountains, white for unity and justice, blue for the natural harbour at Freetown."],
["so","Somalia",AF,"Mogadishu","UN blue, as the UN oversaw its path to independence, with a white star whose five points are the five regions where Somalis live."],
["za","South Africa",AF,"Pretoria","Six colours in a 'Y' shape, for diverse groups converging into one. Adopted in 1994 for the first democratic election."],
["ss","South Sudan",AF,"Juba","Black for the people, red for blood, green for the land, with white lines for peace. The blue triangle is the Nile and the gold star stands for the unity of the states and hope."],
["sd","Sudan",AF,"Khartoum","Arab Liberation red, white, black with a green triangle for Islam and agriculture. Jordan and Palestine use a red triangle instead."],
["tz","Tanzania",AF,"Dodoma","Green (land) and blue (Indian Ocean) split by a black diagonal (the people) edged in gold (minerals). It merges the flags of Tanganyika and Zanzibar."],
["tg","Togo",AF,"Lomé","Five green and yellow stripes for the five regions, with a white star of peace on a red square. Its proportions are often said to follow the golden ratio, though sources disagree."],
["tn","Tunisia",AF,"Tunis","Red with a white disc holding a red crescent and star, derived from the Ottoman flag and adopted in 1831. Türkiye's crescent sits directly on red."],
["ug","Uganda",AF,"Kampala","Black (the people), yellow (sunshine) and red (brotherhood), each repeated twice, with the grey crowned crane, the national bird, at centre."],
["zm","Zambia",AF,"Lusaka","Green for nature with a block of red (the struggle), black (the people) and orange (copper) in the corner. The eagle in flight stands for rising above problems."],
["zw","Zimbabwe",AF,"Harare","Seven stripes: green (agriculture), yellow (minerals), red (blood) and black (the people). The Zimbabwe Bird, a soapstone carving from Great Zimbabwe, sits on a red star."],

["ag","Antigua and Barbuda",AM,"St. John's","A rising sun (a new era) over black (African heritage), blue (the sea) and white (sand), framed by a red 'V' for victory."],
["ar","Argentina",AM,"Buenos Aires","Light blue and white from the cockades of the 1810 May Revolution. The Sun of May at centre is an Inca sun; Uruguay uses the same sun."],
["bs","Bahamas",AM,"Nassau","Aquamarine for the sea, gold for the sun and the land's natural resources, and a black triangle for the strength and determination of the people."],
["bb","Barbados",AM,"Bridgetown","A black trident head for independence from Britain; the shaft is deliberately broken off. Blue for sea and sky, gold for the sand."],
["bz","Belize",AM,"Belmopan","One of the very few national flags with people on it: two woodcutters, one mestizo and one Afro-Belizean, beside a mahogany tree, under a wreath of 50 leaves for 1950, the year the People's United Party came to power."],
["bo","Bolivia",AM,"Sucre (constitutional), La Paz (seat of government)","Red for the blood of heroes, yellow for mineral wealth, green for the fertility of the land. Ghana has the same order with a black star."],
["br","Brazil",AM,"Brasília","Green and the yellow diamond come from the Braganza and Habsburg royal houses. The blue globe shows the Rio sky on 15 November 1889, one star per state plus the Federal District, with the motto 'Order and Progress'."],
["ca","Canada",AM,"Ottawa","The red maple leaf replaced a British ensign in 1965. Red and white have been Canada's official colours since 1921."],
["cl","Chile",AM,"Santiago","Blue for the sky, white for the snow of the Andes, red for the blood shed for independence. A single star as a guide to progress and honour; the design predates the Texas flag."],
["co","Colombia",AM,"Bogotá","Yellow (gold and the land) takes up half the flag, blue is the sky and seas, red is blood. Venezuela and Ecuador share the pattern from the old Gran Colombia; Colombia's is the one with no emblem or stars."],
["cr","Costa Rica",AM,"San José","Blue, white and red. The red centre band was added in 1848 in sympathy with that year's French revolution, on top of the Central American blue-white-blue. Thailand swaps blue and red."],
["cu","Cuba",AM,"Havana","Three blue stripes for the island's three old departments, white for purity, a red triangle for strength and constancy and a lone star. Designed in 1849 by exiles in New York."],
["dm","Dominica",AM,"Roseau","The sisserou parrot, the national bird, on green, with a cross of yellow, black and white for the native people, the fertile soil and the pure water. Ten stars for the ten parishes."],
["do","Dominican Republic",AM,"Santo Domingo","The only national flag to show a Bible, open on the coat of arms. A white cross for salvation divides blue (liberty) and red (blood)."],
["ec","Ecuador",AM,"Quito","Gran Colombia colours with the arms at centre: Chimborazo volcano, the Guayas river and a condor. Colombia has no arms; Venezuela has stars."],
["sv","El Salvador",AM,"San Salvador","Central American blue-white-blue with the arms: a triangle with five volcanoes, a Phrygian cap of liberty and a rainbow, ringed by the country's full name."],
["gd","Grenada",AM,"St. George's","A nutmeg, the island's famous export, sits at the hoist. Seven stars for the seven parishes; red for courage, yellow for sun, green for agriculture."],
["gt","Guatemala",AM,"Guatemala City","Blue, white, blue in vertical stripes, with the resplendent quetzal (liberty) perched on a scroll dated 15 September 1821, the day of Central American independence."],
["gy","Guyana",AM,"Georgetown","The 'Golden Arrowhead': green for forests, gold for mineral wealth, red for zeal, white for the rivers and black for endurance."],
["ht","Haiti",AM,"Port-au-Prince","Legend says Dessalines tore the white stripe out of the French tricolour in 1803, dropping the colour associated with the white colonists. The arms carry the motto 'Unity makes strength'. Liechtenstein's is blue over red with a crown."],
["hn","Honduras",AM,"Tegucigalpa","Central American blue-white-blue with five stars for the five members of the former Federal Republic of Central America."],
["jm","Jamaica",AM,"Kingston","Green for hope and agriculture, gold for sunlight, black for strength and creativity. The original 1962 gloss: 'hardships there are, but the land is green and the sun shineth'."],
["mx","Mexico",AM,"Mexico City","Green, white, red from the 1821 independence army. The eagle on a cactus eating a snake is the Aztec legend of the founding of Tenochtitlan. Italy's tricolour has no emblem."],
["ni","Nicaragua",AM,"Managua","Blue-white-blue with the Central American arms: five volcanoes between two oceans, a rainbow and a Phrygian cap. One of the few flags to include purple (in the rainbow)."],
["pa","Panama",AM,"Panama City","Blue and red for the Conservative and Liberal parties, white for the peace between them; the blue star for purity and the red star for law."],
["py","Paraguay",AM,"Asunción","Red, white, blue like the Netherlands, but the only national flag with different emblems on each side: the national arms on the front and the treasury seal on the back."],
["pe","Peru",AM,"Lima","Red, white, red in vertical bands. Legend says General San Martín saw a flock of red-and-white flamingos take off and took it as a sign. Austria's is horizontal."],
["kn","Saint Kitts and Nevis",AM,"Basseterre","A black diagonal for African heritage carrying two white stars for the two islands (hope and liberty). Green for fertile land, red for the struggle."],
["lc","Saint Lucia",AM,"Castries","A gold and black triangle for the Pitons, the island's twin volcanic peaks, rising from a cerulean blue sea."],
["vc","Saint Vincent and the Grenadines",AM,"Kingstown","Three green diamonds forming a 'V' for the 'Gems of the Antilles'. Blue for sky and sea, yellow for the sun."],
["sr","Suriname",AM,"Paramaribo","Green for the fertile land, white for justice, red for progress, with a yellow star for unity and a golden future."],
["tt","Trinidad and Tobago",AM,"Port of Spain","A black diagonal edged in white on red: red for fire and the sun, black for the earth and dedication, white for water and purity. Adopted at independence in 1962."],
["us","United States",AM,"Washington, D.C.","Thirteen stripes for the original colonies and fifty stars for the states. The 50-star version dates from 1960."],
["uy","Uruguay",AM,"Montevideo","Nine stripes for the nine original departments, with the Sun of May shared with Argentina. Greece has nine stripes too, with a cross instead."],
["ve","Venezuela",AM,"Caracas","Miranda's yellow, blue and red, shared with the old Gran Colombia, with an arc of eight stars: seven for the provinces that declared independence in 1811, plus an eighth for Guayana, added by Bolívar in 1817 and restored in 2006."],

["au","Australia",OC,"Canberra","The Union Jack for British ties, the Southern Cross for its place in the southern sky, and the seven-pointed Commonwealth Star for six states plus the territories. New Zealand's stars are red and it has no Commonwealth Star."],
["fj","Fiji",OC,"Suva","The Union Jack on a light Pacific blue, with a shield showing sugar cane, a coconut palm, bananas and a dove of peace."],
["ki","Kiribati",OC,"Tarawa","A frigatebird (power and freedom) over a rising sun above wavy blue-and-white stripes for the ocean and the three island groups."],
["mh","Marshall Islands",OC,"Majuro","Two rays, orange for courage and white for peace, rise across blue. The star has 24 points for the electoral districts; its four longer points stand for the main cultural centres of Majuro, Jaluit, Wotje and Ebeye."],
["fm","Micronesia",OC,"Palikir","Four white stars for the four states on a blue field for the Pacific. The shade was originally the lighter blue of the UN flag, but a darker blue has been used since 1986."],
["nr","Nauru",OC,"Yaren (de facto)","A yellow line for the equator and a twelve-pointed star for the island's twelve original tribes, placed just below the line because that is where Nauru sits."],
["nz","New Zealand",OC,"Wellington","The Union Jack with four red, white-bordered stars of the Southern Cross. Australia's has five plain white stars plus a large Commonwealth Star."],
["pw","Palau",OC,"Ngerulmud","A golden full moon on light blue sea. The full moon is said to be the best time for fishing, planting and celebrating."],
["pg","Papua New Guinea",OC,"Port Moresby","A bird-of-paradise in flight on red and the Southern Cross on black. Designed by a 15-year-old schoolgirl, Susan Karike, in 1971."],
["ws","Samoa",OC,"Apia","Red for courage, white for purity and blue for freedom, with the Southern Cross in the canton."],
["sb","Solomon Islands",OC,"Honiara","Blue (water) and green (land) divided by a thin yellow stripe (sunshine), with five stars for the five original provinces."],
["to","Tonga",OC,"Nukuʻalofa","Red for the blood of Christ and a red cross in a white canton for Christianity. The constitution states the flag may never be changed."],
["tv","Tuvalu",OC,"Funafuti","A light blue field with the Union Jack in the canton and nine yellow stars in the fly, one for each of the nine islands."],
["vu","Vanuatu",OC,"Port Vila","A boar's tusk (prosperity) around two namele fern fronds (peace) on black for the people, with a yellow 'Y' for the shape of the archipelago and the light of the Gospel. Red for blood, green for the land."]
];
const T1="Caribbean & Atlantic territories",T2="Pacific territories",T3="Europe, Asia & Indian Ocean territories",T4="Nations & regions",T5="Organisations";
const SETS=[T1,T2,T3,T4,T5]; // territories, regions and organisations: not countries, so outside Flag Lord and the country count
// Extra flags: [code, name, set, capital/seat, blurb]
const EXTRA=[
["ai","Anguilla",T1,"The Valley","A British Blue Ensign with the territory's arms: three orange dolphins circling on white above a turquoise band, for endurance, unity and strength, and the sea. The dolphins come from a 1967 flag flown during Anguilla's break from Saint Kitts."],
["aw","Aruba",T1,"Oranjestad","Light blue for the sea around the island, two narrow yellow stripes for abundance and the prosperity brought by gold, aloe and tourism, and a red four-pointed star edged in white for the island itself, the four points of the compass and the many origins of its people. White stands for peace and the beaches. Adopted in 1976."],
["bm","Bermuda",T1,"Hamilton","Unusually for a British territory, a Red Ensign rather than blue. The shield shows a red lion holding a smaller shield on which the Sea Venture wrecks on Bermuda's rocks in 1609, the event that led to settlement."],
["cw","Curaçao",T1,"Willemstad","Blue for the sea and sky, split by a yellow stripe for the sun, with two white stars for Curaçao and its small neighbour Klein Curaçao. The stars' five points stand for the five continents the islanders came from."],
["ky","Cayman Islands",T1,"George Town","A British Blue Ensign with the arms: three green stars on blue-and-white waves for the three islands, a gold lion for England, a turtle and pineapple above, and the motto 'He hath founded it upon the seas'."],
["fk","Falkland Islands",T1,"Stanley","A British Blue Ensign with the arms: a ram for the sheep farming that long sustained the islands, above the ship Desire, whose captain John Davis is credited with the first sighting in 1592, and the motto 'Desire the right'."],
["gl","Greenland",T1,"Nuuk","Erfalasorput, 'our flag': a disc split red over white on a field split white over red. The red half-disc is the sun sinking into the ocean and the white half is icebergs and pack ice, on a white band for the ice cap and a red band for the sea. Adopted in 1985 using the colours of Denmark's flag."],
["gs","South Georgia and the South Sandwich Islands",T1,"King Edward Point","A British Blue Ensign with the arms: a lion holding a torch, a reindeer (introduced by whalers), a fur seal and a macaroni penguin as supporters, and the motto 'Leo terram propriam protegat', the lion shall protect his own land."],
["ms","Montserrat",T1,"Brades (de facto)","A British Blue Ensign with a shield showing a woman in green holding a cross and a harp: Erin, the personification of Ireland, recalling the Irish settlers of the 1600s who gave the island its 'Emerald Isle of the Caribbean' nickname."],
["pr","Puerto Rico",T1,"San Juan","Five red and white stripes with a white star on a blue triangle, designed in 1895 by exiles in New York as a deliberate colour-swap of Cuba's flag. Red for the blood of patriots, white for liberty, the triangle for the three branches of government."],
["sx","Sint Maarten",T1,"Philipsburg","Red over blue with a white triangle at the hoist, the Philippines layout in Dutch colours, with the arms: the courthouse, a sprig of sage, the monument to Dutch-French friendship, and a pelican with the sun."],
["tc","Turks and Caicos Islands",T1,"Cockburn Town","A British Blue Ensign with a yellow shield showing a conch shell, a spiny lobster and a Turk's head cactus, the local products that replaced an earlier badge of salt piles, one of which was mistaken for an igloo at the Admiralty and given a door."],
["vg","British Virgin Islands",T1,"Road Town","A British Blue Ensign with the arms: Saint Ursula in white holding a lamp, surrounded by eleven lamps for her companions, and the motto 'Vigilate', be watchful. Columbus named the islands for the saint and her virgins."],
["vi","United States Virgin Islands",T1,"Charlotte Amalie","A simplified American eagle on white holding a sprig of laurel and three arrows, for the three main islands, between the blue letters V and I. The eagle's shield uses the blue of the US flag."],
["mq","Martinique",T1,"Fort-de-France","Red, green and black, the pan-African colours, in a design used by Martinican independence activists since 1968 and adopted by the island's Assembly in February 2023 after a public vote whose winning entry was withdrawn. It is flown alongside the French tricolour; the old snake flag, from a 1766 edict and linked to the slave trade, was dropped in 2018."],
["sh-hl","Saint Helena",T1,"Jamestown","A British Blue Ensign with a shield: a three-masted ship flying the St George's cross between two cliffs, with the Saint Helena plover, the island's endemic wirebird, in the chief."],
["sh-ac","Ascension Island",T1,"Georgetown","A British Blue Ensign with the arms, granted in 2012 and flown from 2013: a shield of three white terns on a wavy sea with a green chevron, supported by two green turtles, with a sailing ship on a green mound in the crest."],
["sh-ta","Tristan da Cunha",T1,"Edinburgh of the Seven Seas","A British Blue Ensign with the arms: a Tristan longboat above a crown, flanked by two rock lobsters, the island's main export, and the motto 'Our faith is our strength'. The arms date from 2002."],

["as","American Samoa",T2,"Pago Pago","A bald eagle on white flies across a blue field, holding a fue (fly whisk, for wisdom) and an uatogi (war club, for the government's power), traditional Samoan symbols of chiefly authority, in the red, white and blue of the United States."],
["ck","Cook Islands",T2,"Avarua","A British Blue Ensign with a ring of fifteen white stars, one for each of the fifteen islands. The islands are self-governing in free association with New Zealand."],
["gu","Guam",T2,"Hagåtña","A dark blue field with a red border and, at centre, an almond-shaped seal showing a proa sailing in Agana Bay beneath a coconut palm, with the island's name across it. The shape recalls a Chamorro slingstone."],
["mp","Northern Mariana Islands",T2,"Saipan","On blue for the Pacific, a white star for the United States sits on a grey latte stone, the pillar of ancient Chamorro houses, ringed by a mwarmwar, the Carolinian flower garland."],
["nc","New Caledonia",T2,"Nouméa","The Kanak flag flies alongside the French tricolour. Blue for the sky and ocean, red for the blood of the independence struggle, green for the land, with a yellow disc for the sun bearing a black flèche faîtière, the carved spire of a chief's house."],
["nf","Norfolk Island",T2,"Kingston","A Norfolk Island pine in dark green on white between two green bands, in the vertical layout of Canada's flag. The tree is the island's native symbol."],
["nu","Niue",T2,"Alofi","A golden-yellow field, unusual among British-style flags, with the Union Jack in the canton bearing a blue disc and a yellow star, flanked by four more stars for the Southern Cross. Yellow stands for the people's warmth and their ties to New Zealand."],
["pf","French Polynesia",T2,"Papeete","Red and white bands around a disc showing a Polynesian outrigger canoe on blue-and-white waves under a sun, its crew of five drawn as stars standing for the five archipelagos. Flown alongside the French tricolour."],
["pn","Pitcairn Islands",T2,"Adamstown","A British Blue Ensign with arms showing the anchor and Bible of HMS Bounty, whose mutineers settled the island in 1790, on a shield of blue, yellow and green, topped by a wheelbarrow and a miro plant."],
["tk","Tokelau",T2,"None","A Tokelauan canoe in yellow sails toward the Southern Cross on blue, the stars guiding the territory's journey toward the best form of government for its people. Adopted in 2009; Tokelau is administered by New Zealand."],
["wf","Wallis and Futuna",T2,"Mata-Utu","An unofficial local flag: red with four white triangles arranged around the centre, formed by a white saltire, and the French tricolour in the canton. The French flag is the official one."],
["cx","Christmas Island",T2,"Flying Fish Cove","Green and blue divided diagonally, for the land and the sea, with the Southern Cross on the blue, a golden bosun bird (the island's white-tailed tropicbird) on the green, and a gold disc showing a map of the island."],
["cc","Cocos (Keeling) Islands",T2,"West Island","Green and gold, Australia's national colours, with a gold disc holding a palm tree for the islands' tropical plants, a crescent for the islands' Malay Muslim population, and the Southern Cross for Australia, which administers the territory."],

["ax","Åland",T3,"Mariehamn","A red Nordic cross outlined in yellow on blue: Sweden's colours with Finland's red added, for a Swedish-speaking autonomous region of Finland. Officially adopted in 1954."],
["fo","Faroe Islands",T3,"Tórshavn","Merkið, 'the banner': a red Nordic cross outlined in blue on white. White for the sea foam and the clear sky, red and blue for the traditional Faroese colours and the other Nordic flags. First raised in 1919, recognised in 1940."],
["gi","Gibraltar",T3,"Gibraltar","A white field over a red band, with a red three-towered castle and a gold key hanging from its gate: Gibraltar as the key to the Mediterranean. The arms were granted by Spain in 1502."],
["gg","Guernsey",T3,"St Peter Port","The red cross of St George with a gold Norman cross inside it, added in 1985 to distinguish it from England's flag and to recall the island's ties to the Duchy of Normandy, which gave it the gold cross of William the Conqueror's banner."],
["im","Isle of Man",T3,"Douglas","The triskelion, three armoured legs joined at the thigh, on red. The symbol dates from the 13th century and comes with the motto 'Quocunque jeceris stabit', whichever way you throw it, it will stand."],
["je","Jersey",T3,"St Helier","A red saltire on white, in use since at least the 18th century, with the arms of Jersey, three gold leopards on red, added above the centre under a Plantagenet crown in 1981."],
["hk","Hong Kong",T3,"Hong Kong","A white five-petalled Bauhinia blakeana flower, Hong Kong's emblem, on red, with a red star in each petal. Red matches China's flag; the flower stands for harmony between Hong Kong and the mainland. Adopted in 1990 and first flown at the 1997 handover."],
["mo","Macau",T3,"Macau","A white lotus flower above a stylised bridge and water, with five gold stars from China's flag, on green. The lotus is Macau's symbol, and the bridge is the Governor Nobre de Carvalho Bridge. Approved in 1993 and first flown at the 1999 handover from Portugal."],
["io","British Indian Ocean Territory",T3,"Diego Garcia","A British ensign whose field is blue-and-white wavy lines for the Indian Ocean, with the Union Jack in the canton and a palm tree rising above a crown. Granted by Queen Elizabeth II in 1990 for the territory's 25th anniversary."],
["tf","French Southern and Antarctic Lands",T3,"Saint-Pierre, Réunion","The French tricolour in the canton of a blue field, with the territory's monogram TAAF in white and five stars, usually read as its five districts, including the Kerguelen and Crozet islands and Adélie Land in Antarctica."],
["eh","Western Sahara",T3,"Laayoune (claimed); Tifariti (provisional)","The flag of the Sahrawi Arab Democratic Republic: the Palestinian-style black, white and green stripes with a red triangle, plus a red crescent for Islam and a red star for the Arab republic at centre. Used by the Polisario Front, which claims the territory Morocco controls."],
["aq","Antarctica",T3,"None","No official flag, but one widely seen design is a white map of the continent on a UN-style blue field, created by Graham Bartram in 1996, flown at some Antarctic bases and used as the Antarctica emoji. The blue stands for neutrality; the continent is governed by treaty."],

["gb-eng","England",T4,"London","The red cross of Saint George on white, England's patron saint since the 1300s. It is one of the three crosses layered into the Union Jack."],
["gb-sct","Scotland",T4,"Edinburgh","The Saltire: a white diagonal cross on blue for Saint Andrew, who was said to have been crucified on an X-shaped cross. Legend dates it to a battle in 832; it is one of the oldest national flags in use."],
["gb-wls","Wales",T4,"Cardiff","Y Ddraig Goch, the red dragon, on a field split white over green, the Tudor colours. The dragon is a symbol of Wales going back to Welsh legend; the flag was made official only in 1959. Wales is the one home nation not represented on the Union Jack."],
["gb-nir","Northern Ireland",T4,"Belfast","The Ulster Banner: the red cross of St George bearing a white six-pointed star with the Red Hand of Ulster and a crown. It was the government flag from 1953 until 1972 and has no official status now, though it is still used in sport."],
["es-ct","Catalonia",T4,"Barcelona","The Senyera: four red stripes on gold, one of the oldest heraldic designs in Europe, from the arms of the medieval Counts of Barcelona and Crown of Aragon. The same red and gold bars appear today on the coat of arms of Spain."],
["es-ga","Galicia",T4,"Santiago de Compostela","A white field crossed by a diagonal light-blue band, said to echo the old maritime flag of the port of A Coruña. The official version adds the Galician arms: a gold chalice and crosses on blue."],
["es-pv","Basque Country",T4,"Vitoria-Gasteiz","The Ikurriña: a white cross over a green saltire on red, designed in 1894 by the Arana brothers for Biscay. Red for the people, green for the Oak of Gernika and the Basque laws, the white cross for Catholicism."],
["ic","Canary Islands",T4,"Las Palmas and Santa Cruz de Tenerife","White, blue and yellow vertical stripes, with the arms at centre on the official version: seven islands on a shield between two dogs, which the islands' name may come from (Latin canariae, 'of dogs'). Adopted in 1982."],

["eu","European Union",T5,"Brussels","A circle of twelve gold stars on blue, adopted by the Council of Europe in 1955 and taken up by the EU in 1985. The number twelve is a symbol of completeness, not a count of members; it never changes."],
["un","United Nations",T5,"New York","A world map centred on the North Pole, enclosed by olive branches of peace, in white on light blue, a colour chosen as the opposite of red, the colour of war. The emblem was adopted in 1946 and the flag in 1947."],
["arab","Arab League",T5,"Cairo","A gold chain of 22 links, one per member state, surrounding a crescent and the League's name in Arabic, with two olive branches, on green."],
["asean","ASEAN",T5,"Jakarta","Ten rice stalks bound together in a red circle on blue, one for each of the ten members of the Association of Southeast Asian Nations when the flag was adopted in 1997; Timor-Leste became the eleventh member in 2025. Blue for peace and stability, red for courage, white for purity and yellow for prosperity."]
];
const FLAGS=[...RAW.map(([c,n,r,cap,m])=>({c,n,r,cap,m,sov:true})),...EXTRA.map(([c,n,r,cap,m])=>({c,n,r,cap,m,sov:false}))];
const COUNTRIES=FLAGS.filter(f=>f.sov);
const BY=Object.fromEntries(FLAGS.map(f=>[f.c,f]));
